#include <stdio.h>
#include <stdlib.h>

int cmp(const void *a, const void *b) {
    return *((int *) a) - *((int *) b);
}

int main() {
    int size1;
    scanf("%d", &size1);

    int nums1[size1];
    for (int i = 0; i < size1; i++) {
        scanf("%d", &nums1[i]);
    }

    int size2;
    scanf("%d", &size2);

    int nums2[size2];
    for (int i = 0; i < size2; i++) {
        scanf("%d", &nums2[i]);
    }

    int k;
    scanf("%d", &k);

    int size = size1 * size2;

    int pairs[size];
    int pairs_size = 0;

    for (int i = 0; i < size1; i++) {
        for (int j = 0; j < size2; j++) {
            pairs[pairs_size++] = nums1[i] + nums2[j];
        }
    }

    qsort(pairs, pairs_size, sizeof(int), cmp);

    int sum = 0;
    for (int i = 0; i < k; i++) {
        sum += pairs[i];
    }

    printf("%d\n", sum);

    return 0;
}
